    if (String(rawBudget).trim() === '' || String(rawReserve).trim() === '' || String(rawBuffer).trim() === '') throw new Error('invalid_config');
    var budget = Number(rawBudget), reserve = Number(rawReserve), buffer = Number(rawBuffer);
    if (!Number.isFinite(budget) || budget < 0 || !Number.isFinite(reserve) || reserve < 0 || !Number.isFinite(buffer) || buffer < 5 || buffer > 50) throw new Error('invalid_config');
    var kinds = Object.keys(labels).filter(function (kind) { return root.querySelector('[data-gta-kind="' + kind + '"]').checked; });
    var enabled = root.querySelector('[data-gta-enabled]').checked; if (enabled && !kinds.length) throw new Error('invalid_config');
    return { enabled: enabled, budget: budget, reserve: reserve, target: (100 - buffer) / 100, kinds: kinds };
  }
  function updateActions() {
    root.querySelectorAll('[data-gta-edit]').forEach(function (input) { input.disabled = busy || !loaded; });
    root.querySelector('[data-gta-save]').disabled = busy || !loaded;
    root.querySelector('[data-gta-refresh]').disabled = busy;
    root.querySelector('[data-gta-run]').disabled = busy || !loaded || dirty || !state || !state.config || state.config.enabled !== true;
    text('[data-gta-unsaved]', dirty ? 'Unsaved changes. Save settings before queuing projects.' : '');
    root.querySelector('[data-gta-busy]').textContent = busy ? 'Working…' : '';
  }
  function render() {
    if (!root) return;
    var d = state && state.demand || {}, delivery = state && state.delivery || {}, b = state && state.budget || {}, p = state && state.projects || {}, status = state && state.status || {};
    text('[data-gta-budget-label]', 'Monthly budget (' + currency() + ' billions)');
    text('[data-gta-reserve-label]', 'Cash reserve (' + currency() + ' billions)');
    text('[data-gta-currency-note]', 'All amounts are billions of your treasury currency (' + currency() + '). The monthly budget covers planned scheduled commitments for all active transport construction, including manual construction and upgrades. Actual invoices can vary with construction speed. Lowering the budget never cancels active projects. The cash reserve is a floor for approving new projects, not frozen funds; other government spending can affect the treasury.');
    text('[data-gta-load]', fmt(d.load)); text('[data-gta-capacity]', fmt(d.capacity)); text('[data-gta-pending]', fmt(d.pendingCapacity));
    text('[data-gta-utilization]', pct(d.utilization)); text('[data-gta-target-capacity]', fmt(d.targetCapacity));
    var rate = finite(delivery.rate) ? Number(delivery.rate) : finite(d.deliveryRate) ? Number(d.deliveryRate) : null;
    var missing = rate == null ? null : Math.max(0, 1 - rate);
    var hasUnmet = missing != null && missing > 0.00000001 || finite(delivery.unmetLoad) && Number(delivery.unmetLoad) > 0.00000001;
    text('[data-gta-delivery]', pct(rate)); text('[data-gta-missing]', pct(missing));
    text('[data-gta-requested]', fmt(delivery.requestedLoad)); text('[data-gta-delivered-load]', fmt(delivery.deliveredLoad)); text('[data-gta-unmet-load]', fmt(delivery.unmetLoad));
    text('[data-gta-delivery-summary]', !state ? 'Check the network to see actual delivery.' : rate == null ? 'Waiting for route delivery information.' : hasUnmet ? pct(missing) + ' of transport demand is still unmet. Land capacity alone does not remove pipeline, port, or foreign route bottlenecks.' : 'Current transport demand is fulfilled.');
    renderBlockers(delivery.blockers); text('[data-gta-cap]', money(b.monthlyCap));
    text('[data-gta-committed]', money(b.monthlyCommitted)); text('[data-gta-available]', money(b.monthlyAvailable));
    text('[data-gta-cash]', money(b.cash)); text('[data-gta-cash-available]', money(b.cashAvailable));
    text('[data-gta-outstanding]', money(b.outstanding)); text('[data-gta-reserve-value]', money(b.reserve));
    var coverage = !state ? 'Check the network to see land capacity.' : d.calibrated === false ? 'Waiting for the land network to update.' : finite(d.additionalCapacity) && Number(d.additionalCapacity) <= 0 ? 'National land capacity meets the target.' + (hasUnmet ? ' Other routes still have unmet demand.' : '') : finite(d.additionalCapacity) ? fmt(d.additionalCapacity) + ' more capacity needed to meet the national land target.' : 'Land capacity will appear after the transport network updates.';
    text('[data-gta-coverage]', coverage);
    text('[data-gta-status]', typeof status.message === 'string' && status.message ? status.message : state && state.config && state.config.enabled ? 'Automatic construction is enabled.' : 'Automatic construction is off.');
    text('[data-gta-project-count]', fmt(p.active) + ' active · ' + fmt(p.automatic) + ' automatic');
    var rows = root.querySelector('[data-gta-projects]'); rows.replaceChildren();
    var items = Array.isArray(p.items) ? p.items : [];
    if (!items.length) rows.appendChild(element('p', 'gta-muted', 'No active transport projects.'));
    else {
      var table = element('table', 'gta-table'); table.setAttribute('aria-label', 'Active transport projects');
      var head = element('thead'), tr = element('tr'); ['Project', 'Length', 'Monthly cost', 'Time left'].forEach(function (label) { var cell = element('th', '', label); cell.scope = 'col'; tr.appendChild(cell); }); head.appendChild(tr); table.appendChild(head);
      var body = element('tbody');
      items.forEach(function (item) { var row = element('tr'); var title = (item.label || labels[item.kind] || 'Transport') + (item.automatic ? ' · automatic' : '') + (item.provinceName ? ' · ' + item.provinceName : '');
        [title, finite(item.km) ? fmt(item.km) + ' km' : '—', money(item.monthly), finite(item.monthsLeft) ? fmt(item.monthsLeft) + ' months' : '—'].forEach(function (value) { row.appendChild(element('td', '', value)); }); body.appendChild(row); });
      table.appendChild(body); rows.appendChild(table);
    }
    text('[data-gta-history]', Array.isArray(state && state.history) && state.history.length ? state.history.length + ' automatic projects recorded in this campaign.' : 'No automatic projects recorded yet.');
    updateActions();
  }
  function renderBlockers(blockers) {
