      var foreignSerial = reason === 'foreign_serial_capacity';
      var ownedSerial = reason === 'serial_upgrade_required';
      var foreign = /foreign|external|other_country/.test(scope) || /foreign/.test(reason);
      var queued = /queue|pending/.test(reason) || /queue|pending/.test(scope);
      var kind = blocker.mode === 'sea' || blocker.mode === 'gas_terminal' || blocker.mode === 'oil_terminal' ? 'port' : blocker.mode;
      var selected = kind === 'land' ? saved.kinds.some(function (value) { return value === 'road' || value === 'motorway' || value === 'rail'; }) : saved.kinds.indexOf(kind) >= 0;
      var knownType = kind === 'land' || !!labels[kind];
      var disabled = /disabled|not_enabled/.test(reason) || /disabled/.test(scope) || !foreign && blocker.actionable === true && knownType && !selected;
      var action = foreignSerial ? 'Requires foreign upgrade' : ownedSerial ? 'Upgrade all limiting sections together' : reason === 'selected_route_unavailable' ? 'Waiting for route forecast' : foreign ? 'Foreign-controlled' : queued ? 'Already queued' : disabled ? 'Disabled type' : blocker.actionable ? 'You can expand' : 'No supported expansion';
      var control = (foreignSerial ? 'Foreign section limits route' : ownedSerial ? 'Several sections limit route' : foreign ? 'Foreign-controlled' : scope === 'shared' ? 'Shared control' : scope === 'route' ? 'Route constraint' : 'Your network') + (blocker.ownerName ? ' · ' + blocker.ownerName : '');
      var actionText = action + (disabled && !foreign && !queued && !ownedSerial ? kind === 'port' ? ' · enable Ports and save settings' : ' · enable this type and save settings' : '');
      [blocker.label || labels[kind] || 'Transport route', control, fmt(blocker.unmetLoad), actionText].forEach(function (value) { row.appendChild(element('td', '', value)); }); body.appendChild(row);
    }); table.appendChild(body); rows.appendChild(table);
  }
  async function action(kind) {
    if (busy || !opened) return; var token = generation; busy = true; notice(''); updateActions();
    try {
