      if (token !== generation) return;
      if (kind === 'save' || !dirty) populate(); render();
      notice(kind === 'save' ? 'Settings saved. ' + (state.config.enabled ? 'Automatic construction is enabled.' : 'Automatic construction is off.') : kind === 'run' ? 'Construction checked. See the status below.' : 'Construction information refreshed.');
