    populate(); render(); notice(''); root.hidden = false; root.querySelector('[data-gta-close]').focus(); action('refresh');
  }
  function mount() {
    if (root) return;
    var css = element('style'); css.id = 'gta-style'; css.textContent = `
#gta-dialog[hidden]{display:none!important}#gta-dialog{position:fixed;inset:0;z-index:10090;background:rgba(5,10,16,.78);display:flex;align-items:center;justify-content:center;padding:24px;color:#e9e5dc;font:14px/1.5 system-ui,sans-serif;box-sizing:border-box}#gta-dialog *{box-sizing:border-box}#gta-dialog .gta-panel{width:min(1020px,100%);max-height:92vh;overflow:auto;background:#17212b;border:1px solid #56616b;border-radius:10px;box-shadow:0 20px 80px #0009;padding:26px}#gta-dialog .gta-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}#gta-dialog h2{font-size:23px;margin:0 0 6px;color:#f4e8d3}#gta-dialog h3{font-size:16px;margin:0 0 12px;color:#e5c795}#gta-dialog p{margin:6px 0 12px}#gta-dialog .gta-land-title{margin-top:24px}#gta-dialog .gta-muted{color:#aeb9c4}#gta-dialog .gta-error{color:#ffb9a6}#gta-dialog .gta-grid{min-width:0;display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}#gta-dialog .gta-box{min-width:0;background:#101923;border:1px solid #394753;border-radius:7px;padding:18px}#gta-dialog .gta-wide{grid-column:1/-1}#gta-dialog .gta-enable{display:flex;align-items:center;gap:10px;font-weight:650;font-size:15px;margin-bottom:14px}#gta-dialog .gta-kinds{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:16px}#gta-dialog label{cursor:pointer}#gta-dialog input[type=checkbox]{accent-color:#d4ae73;width:17px;height:17px;vertical-align:middle;margin:0 7px 0 0}#gta-dialog .gta-field{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:12px 0}#gta-dialog .gta-field input{width:130px;background:#222f3b;color:#fff;border:1px solid #69727b;border-radius:4px;padding:7px;font:inherit}#gta-dialog .gta-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}#gta-dialog button{border:1px solid #73808c;background:#263746;color:#efe9df;border-radius:5px;padding:9px 14px;font:inherit;cursor:pointer}#gta-dialog button.gta-primary{background:#d2ad75;color:#18202a;border-color:#d2ad75;font-weight:650}#gta-dialog button:disabled{opacity:.45;cursor:default}#gta-dialog button:focus-visible,#gta-dialog input:focus-visible{outline:2px solid #ecc58a;outline-offset:3px}#gta-dialog .gta-kv{display:flex;justify-content:space-between;gap:16px;padding:5px 0;border-bottom:1px solid #2a3540}#gta-dialog .gta-kv b{font-variant-numeric:tabular-nums;white-space:nowrap}#gta-dialog .gta-notice{min-height:22px;margin-top:12px}#gta-dialog .gta-table-wrap{min-width:0;max-width:100%;overflow:auto}#gta-dialog .gta-table{width:100%;border-collapse:collapse;text-align:left}#gta-dialog th,#gta-dialog td{padding:8px 10px;border-bottom:1px solid #35414c}#gta-dialog th{color:#acb9c5;font-weight:500}#gta-dialog td:not(:first-child){white-space:nowrap}#gta-dialog .gta-note{font-size:12px;color:#aeb9c4;margin-top:12px}#gta-dialog [data-gta-unsaved]{color:#e9c895;font-size:12px}@media(max-width:720px){#gta-dialog{padding:8px}#gta-dialog .gta-panel{padding:16px}#gta-dialog .gta-grid{grid-template-columns:1fr}#gta-dialog .gta-wide{grid-column:auto}#gta-dialog .gta-field{flex-wrap:wrap}}`;
    document.head.appendChild(css);
    root = element('div'); root.id = 'gta-dialog'; root.hidden = true;
    root.innerHTML = `<section class="gta-panel" role="dialog" aria-modal="true" aria-labelledby="gta-title" aria-describedby="gta-description" tabindex="-1">
<div class="gta-head"><div><h2 id="gta-title">Auto transport construction</h2><p id="gta-description" class="gta-muted">Expand your land network, pipelines, and ports as transport demand grows.</p></div><button type="button" data-gta-close aria-label="Close auto transport construction">Close</button></div>
<div class="gta-grid"><section class="gta-box"><h3>Construction settings</h3>
<label class="gta-enable"><input type="checkbox" data-gta-edit data-gta-enabled>Enable automatic construction</label>
<div class="gta-kinds"><label><input type="checkbox" data-gta-edit data-gta-kind="road">Roads</label><label><input type="checkbox" data-gta-edit data-gta-kind="motorway">Freeways</label><label><input type="checkbox" data-gta-edit data-gta-kind="rail">Rail</label><label><input type="checkbox" data-gta-edit data-gta-kind="gas_pipeline">Gas pipelines</label><label><input type="checkbox" data-gta-edit data-gta-kind="oil_pipeline">Oil pipelines</label><label><input type="checkbox" data-gta-edit data-gta-kind="port">Ports</label></div>
<p class="gta-note" data-gta-type-note>Pipelines and ports are opt-in. Select their checkboxes and save settings to allow upgrades to your own infrastructure. Foreign-controlled routes cannot be expanded here.</p>
